Q a=exact(.2),k=exact(.1),trace=-(3*a+2*k)/2,delta=sqrt(a*a+a*a/4),scale=exp(trace),sh=sinh(delta)/delta;Q x0=scale*(cosh(delta)-a*sh/2),x1=scale*a*sh;add("diffusion.x0",x0);add("diffusion.x1",x1);add("diffusion.v00",exact(.1)*exact(.1)*x0*x0);add("diffusion.c01",exact(.1)*exact(.1)*x0*x1);add("diffusion.v11",exact(.1)*exact(.1)*x1*x1);
